require_once __DIR__.'/app/lib/Security.php';
Security::start();$u=Security::requireRole(['reviewer','admin','super_admin']);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>External Authority | TechSelectAI</title><style>body{font-family:Inter,Arial,sans-serif;background:#f7f9fc;color:#14213d;margin:0}main{max-width:1250px;margin:auto;padding:28px}.grid{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}.card,.panel{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:16px}.panel{margin-top:18px}.row{display:grid;grid-template-columns:2fr 1fr 1fr;gap:10px}label{display:block;font-size:12px;font-weight:700;margin:8px 0 4px}input,select,textarea{width:100%;box-sizing:border-box;padding:9px;border:1px solid #cbd5e1;border-radius:8px}textarea{min-height:80px}button{padding:9px 13px;border:0;border-radius:8px;background:#2563eb;color:#fff;cursor:pointer}.secondary{background:#475569}table{width:100%;border-collapse:collapse;margin-top:14px;background:#fff}th,td{padding:9px;border-bottom:1px solid #eef2f7;text-align:left;vertical-align:top;font-size:13px}.muted{color:#64748b}.ok{color:#166534}.err{color:#b91c1c}.badge{padding:3px 7px;border-radius:999px;background:#eef2ff;display:inline-block;font-size:11px}@media(max-width:800px){.grid,.row{grid-template-columns:1fr}table{display:block;overflow:auto}}</style></head><body><main><p><a href="/admin">← Admin</a></p><h1>External Authority & Backlinks</h1><p class="muted">Track legitimate external profiles, publications, partner/customer/vendor mentions and resulting backlinks. This tool does not automate outreach or link building.</p><div id="summary" class="grid"></div><section class="panel"><h2>Add / edit authority source</h2><input type="hidden" id="id"><div class="row"><div><label>Source name</label><input id="source_name" placeholder="Publication or site name"></div><div><label>Domain</label><input id="domain" placeholder="example.com"></div><div><label>Source type</label><select id="source_type"><option>directory</option><option>partner</option><option>industry_publication</option><option>company_profile</option><option>customer_mention</option><option>vendor_mention</option><option>thought_leadership</option><option>other</option></select></div></div><div class="row"><div><label>Source URL</label><input id="source_url" placeholder="https://..."></div><div><label>Authority tier</label><select id="authority_tier"><option>high</option><option selected>medium</option><option>low</option></select></div><div><label>Relevance (1–5)</label><input id="relevance_score" type="number" min="1" max="5" value="3"></div></div><div class="row"><div><label>TechSelectAI asset path</label><input id="techselect_asset_path" placeholder="/methodology or /guides/..."></div><div><label>Outreach status</label><select id="outreach_status"><option>prospect</option><option>researching</option><option>ready</option><option>contacted</option><option>follow_up</option><option>accepted</option><option>declined</option><option>published</option><option>paused</option></select></div><div><label>Backlink status</label><select id="backlink_status"><option>not_published</option><option>active</option><option>lost</option><option>removed</option></select></div></div><div class="row"><div><label>Published URL</label><input id="published_url" placeholder="https://..."></div><div><label>Link type</label><select id="link_type"><option value="">—</option><option>editorial</option><option>profile</option><option>partner</option><option>customer</option><option>vendor</option><option>directory</option><option>other</option></select></div><div><label>Rel attribute</label><input id="rel_attribute" placeholder="nofollow / sponsored / ugc / blank"></div></div><label>Intended context</label><input id="intended_context" placeholder="Natural editorial context; do not force exact-match anchor text"><div class="row"><div><label><input id="mention_requires_approval" type="checkbox" style="width:auto"> Mention requires approval</label></div><div><label><input id="mention_approved" type="checkbox" style="width:auto"> Approval received</label></div><div><label>Next action date</label><input id="next_action_at" type="datetime-local"></div></div><label>Next action</label><input id="next_action"><label>Notes / approval notes</label><textarea id="notes"></textarea><p><button onclick="save()">Save</button> <button class="secondary" onclick="resetForm()">Clear</button></p><div id="msg"></div></section><section class="panel"><h2>Authority pipeline</h2><table><thead><tr><th>Source</th><th>Type</th><th>Outreach</th><th>Backlink</th><th>Asset</th><th>Next action</th><th></th></tr></thead><tbody id="rows"></tbody></table></section></main><script>
const fields=['source_name','domain','source_url','source_type','authority_tier','relevance_score','techselect_asset_path','outreach_status','backlink_status','published_url','link_type','rel_attribute','intended_context','next_action_at','next_action','notes'];let data=[];
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
async function api(url,opt={}){opt.headers={...(opt.headers||{}),'Content-Type':'application/json','X-CSRF-Token':localStorage.getItem('csrf')||''};let r=await fetch(url,opt);let d=await r.json().catch(()=>({error:'Invalid response'}));if(!r.ok)throw new Error(d.error||'Request failed');return d}
async function load(){try{let d=await api('/api/authority-sources');data=d.sources;let s=d.summary;document.getElementById('summary').innerHTML=['total','prospects','contacted','active_backlinks','lost_backlinks'].map(k=>`<div class="card"><small>${esc(k.replaceAll('_',' '))}</small><h2>${esc(s[k])}</h2></div>`).join('');document.getElementById('rows').innerHTML=data.map(x=>`<tr><td><strong>${esc(x.source_name)}</strong><br>${esc(x.domain)}${x.published_url?`<br><a target="_blank" rel="noopener" href="${esc(x.published_url)}">published link</a>`:''}</td><td>${esc(x.source_type)}<br><span class="badge">${esc(x.authority_tier)}</span></td><td>${esc(x.outreach_status)}</td><td>${esc(x.backlink_status)}</td><td>${esc(x.techselect_asset_path||'')}</td><td>${esc(x.next_action||'')}<br>${esc(x.next_action_at||'')}</td><td><button class="secondary" onclick="edit(${x.id})">Edit</button></td></tr>`).join('')}catch(e){msg(e.message,false)}}
function payload(){let b={};fields.forEach(k=>b[k]=document.getElementById(k).value);b.relevance_score=+b.relevance_score;b.mention_requires_approval=document.getElementById('mention_requires_approval').checked;b.mention_approved=document.getElementById('mention_approved').checked;return b}
async function save(){try{let id=document.getElementById('id').value;await api(id?'/api/authority-sources/'+id:'/api/authority-sources',{method:id?'PATCH':'POST',body:JSON.stringify(payload())});msg('Saved and audited.',true);resetForm();await load()}catch(e){msg(e.message,false)}}
function edit(id){let x=data.find(v=>+v.id===+id);if(!x)return;document.getElementById('id').value=x.id;fields.forEach(k=>{let el=document.getElementById(k);if(el)el.value=(x[k]??'').toString().replace(' ','T')});document.getElementById('mention_requires_approval').checked=+x.mention_requires_approval===1;document.getElementById('mention_approved').checked=+x.mention_approved===1;scrollTo({top:0,behavior:'smooth'})}
function resetForm(){document.getElementById('id').value='';fields.forEach(k=>{let el=document.getElementById(k);if(!el)return;if(k==='relevance_score')el.value='3';else if(k==='authority_tier')el.value='medium';else if(k==='outreach_status')el.value='prospect';else if(k==='backlink_status')el.value='not_published';else if(k==='source_type')el.value='directory';else el.value=''});document.getElementById('mention_requires_approval').checked=false;document.getElementById('mention_approved').checked=false}
function msg(t,ok){let m=document.getElementById('msg');m.className=ok?'ok':'err';m.textContent=t}
load();
</script></body></html>